# Correct segment extraction that ignores background
def get_segments_correct(grid):
    segments = []
    # Find background color (most common or first non-empty cell's neighbor)
    bg = None
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0:  # skip empty grids
                bg = grid[r][c]
                break
        if bg is not None:
            break

    if bg is None:
        bg = 0

    for r in range(len(grid)):
        color = None
        for c in range(len(grid[0])):
            val = grid[r][c]
            if val != bg and val != 0 and color is None:
                color = val
                segments.append((r, color))
            elif val == bg or val == 0:
                if color is not None:
                    color = None
    return segments

